use vstd::prelude::*;

verus! {

fn clip(a: Vec<i8>, min: i8, max: i8) -> (result: Vec<i8>)
    requires
        // Lower bound strictly less than upper bound
        min < max,
    ensures
        // The resulting vector has the same length as the input
        result.len() == a.len(),
    ensures
        // For each index i, result[i] is the clipped value of a[i]
        forall |i: usize|
            i < a.len() ==>
                let ai = a.index(i);
                let ri = result.index(i);
                if ai < min {
                    ri == min
                } else if ai > max {
                    ri == max
                } else {
                    ri == ai
                },
    ensures
        // Every element of result lies in [min, max]
        forall |i: usize|
            i < result.len() ==>
                min <= result.index(i) <= max,
{
    let mut res: Vec<i8> = Vec::new();
    let mut idx: usize = 0;
    while idx < a.len()
        invariant
            // idx never exceeds the original length
            idx <= a.len(),
            // res has been built up to length idx
            res.len() == idx,
            // The clipping property holds for all positions < idx
            forall |j: usize|
                j < idx ==>
                    let aj = a.index(j);
                    let rj = res.index(j);
                    if aj < min {
                        rj == min
                    } else if aj > max {
                        rj == max
                    } else {
                        rj == aj
                    },
        decreases
            // Show the loop terminates
            a.len() - idx,
    {
        let ai = a.index(idx);
        let clipped = if ai < min {
            min
        } else if ai > max {
            max
        } else {
            ai
        };
        res.push(clipped);
        idx = idx + 1;
    }
    res
}

}

